#[test]
fn test_hx_fill_measures_the_hidden_columns() {
    let fw: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let feats: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ow: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cg: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let refs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let gv: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let h0: i32 = ht_hword(fw, feats, et, 0, 0, 104, 101, 200);
    let h1: i32 = ht_hword(fw, feats, et, 1000, 0, 109, 111, 400);
    let h2: i32 = ht_hword(fw, feats, et, 2000, 0, 120, 121, -1);
    let o0: i32 = ht_oword(ow, feats, et, 0, 104, 101, 120, 100);
    let o1: i32 = ht_oword(ow, feats, et, 1000, 109, 111, 80, 100);
    let g0: i32 = ht_group(cg, refs, h0, 2, o0, 2, 950);
    let g1: i32 = ht_group(cg, refs, h2, 1, 0, 0, -1);
    while crate::port::cells_len(gv) < ag_count() {
        crate::port::cells_push(gv, 0);
    }
    hx_fill(g0, cg, refs, fw, et, feats, ow, gv);
    crate::testport::assert_eq(crate::port::cells_at(gv, ag_hlatin()), 1, "Latin hidden words are read by the engine");
    crate::testport::assert_eq(crate::port::cells_at(gv, ag_hink()), 300, "the mean ink of the two hidden words");
    crate::testport::assert_eq(crate::port::cells_at(gv, ag_hinkwin()), 1, "300 against 100: the hidden ink agrees better");
    crate::testport::assert_eq(crate::port::cells_at(gv, ag_margin()), 80, "the lowest margin of the OCR words");
    crate::testport::assert_eq(crate::port::cells_at(gv, ag_pageocr()), 0, "a group with OCR has no page count");
    crate::testport::assert_eq(crate::port::cells_at(gv, ag_hsplit()), 0, "two words and two words: no split");
    crate::testport::assert_eq(crate::port::cells_at(gv, ag_hsame()), 1, "and one segmentation");
    hx_fill(g1, cg, refs, fw, et, feats, ow, gv);
    crate::testport::assert_eq(crate::port::cells_at(gv, ag_hink()), -1, "ink not measured");
    crate::testport::assert_eq(crate::port::cells_at(gv, ag_hinkwin()), -1, "so the comparison is not made");
    crate::testport::assert_eq(crate::port::cells_at(gv, ag_margin()), -1, "no OCR word: no margin");
    crate::testport::assert_eq(crate::port::cells_at(gv, ag_pageocr()), 2, "the page's OCR words, for a group with none");
}
