#[test]
fn test_a_hidden_layer_and_ocr_that_agree_give_the_hidden_text_both_sources() {
    let fw: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let fl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let feats: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ow: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cg: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let refs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let nfw: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let nfl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let fv: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let fx: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let afa: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let h0: i32 = ht_hword(fw, feats, et, 0, 0, 104, 101, -1);
    let h1: i32 = ht_hword(fw, feats, et, 1000, 0, 109, 111, -1);
    let o0: i32 = ht_oword(ow, feats, et, 0, 72, 101, 500, -1);
    let o1: i32 = ht_oword(ow, feats, et, 1000, 77, 79, 990, -1);
    ht_line(fl, 2);
    // the first agrees (case folded), the second does not
    ht_group(cg, refs, h0, 1, o0, 1, 950);
    ht_group(cg, refs, h1, 1, o1, 1, 200);
    crate::testport::assert_eq(ht_run(cg, refs, fw, fl, et, feats, ow, nfw, nfl, fv, fx, afa), 2, "two groups decided");
    crate::testport::assert_eq(fw_count(nfw), 2, "two words");
    crate::testport::assert_eq(fv_get(fv, 0, 2), 310, "agreement: rule 310");
    crate::testport::assert_eq(fv_get(fv, 0, 3), 950, "confidence up");
    crate::testport::assert_eq(crate::port::cells_at(nfw, 11), crate::port::cells_at(fw, 11), "the hidden text's own code points (h, e), not OCR's (H, e)");
    crate::testport::assert_eq(crate::port::cells_at(et, crate::port::cells_at(nfw, 11)), 104, "the first letter is the hidden word's");
    crate::testport::assert_eq(crate::port::cells_at(nfw, 23), 6, "src: hidden-text and ocr both");
    crate::testport::assert_eq(fv_get(fv, 1, 2), 322, "disagreement: rule 322");
    crate::testport::assert_eq(fv_get(fv, 1, 1), 4, "OCR's word");
    crate::testport::assert_eq(crate::port::cells_at(et, crate::port::cells_at(nfw, 24 + 11)), 77, "this run's OCR text");
    crate::testport::assert_eq(crate::port::cells_at(nfw, 24 + 17), -1, "no glyph run: the word is OCR's");
    crate::testport::assert_eq(crate::port::cells_at(nfw, 24 + 1), 1000, "the hidden word's geometry");
}
